'use strict';
/* Forever Ref – static single-page browser over data/*.js generated by build.py */
const M = window.FR_META, ITEMS = window.FR_ITEMS, SPELLS = window.FR_SPELLS, PROFS = window.FR_PROFS,
      CLS = window.FR_CLASSES, SETS = window.FR_SETS, ZONES = window.FR_ZONES;
const QNAME = ['Poor', 'Common', 'Uncommon', 'Rare', 'Epic', 'Legendary', 'Artifact', 'Heirloom'];
const BOND = {1: 'Binds when picked up', 2: 'Binds when equipped', 3: 'Binds when used', 4: 'Quest Item', 5: 'Quest Item'};
const POWER = {0: 'Mana', 1: 'Rage', 2: 'Focus', 3: 'Energy', 6: 'Runic Power'};
const TRIG = {0: 'Use', 1: 'Equip', 2: 'Chance on hit', 5: 'Use', 6: 'Teaches'};
const WH = 'https://www.wowhead.com/forever/';
const ICON = 'https://wow.zamimg.com/images/wow/icons/';
/* Tooltip order: Str, Agi, Sta, Int, Spi first, resistances last, everything else by id (matches the Forever client). */
const STAT_ORDER = {4: 0, 3: 1, 7: 2, 5: 3, 6: 4};
const RESIST = new Set([51, 52, 53, 54, 55, 56]);
/* Short labels as the Forever client shows them ("+20 Hit"); anything not listed uses the name from meta. */
const STAT_LABEL = {12: 'Defense', 13: 'Dodge', 14: 'Parry', 15: 'Shield Block', 31: 'Hit', 32: 'Critical Strike', 36: 'Haste', 37: 'Expertise',
  41: 'Healing Done', 42: 'Damage Done', 44: 'Armor Penetration', 47: 'Spell Penetration', 48: 'Block Value', 50: 'Bonus Armor'};
const REP = ['Hated', 'Hostile', 'Unfriendly', 'Neutral', 'Friendly', 'Honored', 'Revered', 'Exalted'];
const FOREVER_STAT_MIN = 83;

const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));
const num = v => (Math.round(v * 10) / 10).toString();
const $ = sel => document.querySelector(sel);

function icon(name, size) {
  size = size || 'medium';
  const n = name || 'inv_misc_questionmark';
  return `<img class="ico ${size}" src="${ICON}${size}/${n}.jpg" loading="lazy" alt="" onerror="this.onerror=null;this.src='${ICON}${size}/inv_misc_questionmark.jpg'">`;
}
function itemLink(id, o) {
  o = o || {};
  const it = ITEMS[id];
  if (!it) return `<a href="${WH}item=${id}" class="ext" target="_blank">item #${id}</a>`;
  return `<a class="q${it.q}" href="#/item/${id}" data-item="${id}">${o.noicon ? '' : icon(it.ic, o.size)}${esc(it.n)}</a>${o.count > 1 ? ` <span class="muted">×${o.count}</span>` : ''}${o.badges ? badges(it) : ''}`;
}
function spellLink(id, o) {
  o = o || {};
  const s = SPELLS[id];
  if (!s) return `<a href="${WH}spell=${id}" class="ext" target="_blank">spell #${id}</a>`;
  return `<a href="#/spell/${id}" data-spell="${id}">${o.noicon ? '' : icon(s.ic, o.size)}${esc(s.n)}</a>${o.rank && s.r ? ` <span class="muted small">${esc(s.r)}</span>` : ''}${o.badges ? badges(s.sk || s) : ''}`;
}
function badges(x) {
  let h = '';
  if (x.new) h += '<span class="badge new" title="Not in Classic Era">NEW</span>';
  if (x.mod || x.chg) h += `<span class="badge mod" title="${esc((x.mod || x.chg).join(', '))}">CHANGED</span>`;
  return h;
}
function money(c) {
  if (!c) return '';
  const g = Math.floor(c / 10000), s = Math.floor(c / 100) % 100, cp = c % 100;
  let h = '<span class="money">';
  if (g) h += `<span class="g">${g}</span>`;
  if (g || s) h += `<span class="s">${s}</span>`;
  h += `<span class="c">${cp}</span></span>`;
  return h;
}
function dur(ms) {
  if (ms < 0) return 'until cancelled';
  const s = ms / 1000;
  if (s < 60) return num(s) + ' sec';
  if (s < 3600) return num(s / 60) + ' min';
  if (s < 86400) return num(s / 3600) + (s === 3600 ? ' hr' : ' hrs');
  return num(s / 86400) + ' days';
}
function subName(c, sc) { return M.itemSubClasses[c + '_' + sc] || M.itemClasses[c] || ''; }
function classList(mask) {
  return Object.keys(M.classes).filter(c => mask & (1 << (c - 1))).map(c => M.classes[c]).join(', ');
}
function two(a, b) { return `<div class="two"><span>${a}</span><span>${b}</span></div>`; }

/* ---------------------------------------------------------------- tooltips */
function statLine(st, v) {
  const sign = v < 0 ? '-' : '+';
  if (st === 43) return `<div>Restores ${sign}${Math.abs(v)} mana per 5 sec.</div>`;
  if (st === 46) return `<div>Restores ${sign}${Math.abs(v)} health per 5 sec.</div>`;
  const label = STAT_LABEL[st] || M.stats[st] || ('Stat ' + st);
  const note = st >= FOREVER_STAT_MIN ? ' <span class="grey" title="Stat kind that only exists in Forever; name inferred from the client string table">*</span>' : '';
  return `<div>${sign}${Math.abs(v)} ${esc(label)}${note}</div>`;
}
function sortStats(list) {
  const key = s => (s[0] in STAT_ORDER ? STAT_ORDER[s[0]] : RESIST.has(s[0]) ? 1000 + s[0] : 100 + s[0]);
  return list.slice().sort((a, b) => key(a) - key(b));
}
function itemTip(id, full) {
  const it = ITEMS[id];
  if (!it) return '';
  const L = [`<div class="name q${it.q}">${esc(it.n)}${full ? '' : badges(it)}</div>`];
  L.push(`<div class="y">Item Level ${it.il}</div>`);
  if (it.b) L.push(`<div>${BOND[it.b] || ''}</div>`);
  if (it.mc === 1) L.push('<div>Unique</div>');
  else if (it.mc > 1) L.push(`<div>Unique (${it.mc})</div>`);
  if (it.lc) L.push(`<div>Unique-Equipped: ${esc(it.lc[0])} (${it.lc[1]})</div>`);
  const slot = M.invTypes[it.it], sub = subName(it.c, it.sc);
  if (it.cs) L.push(`<div>${it.cs} Slot ${esc(sub)}</div>`);
  else if (slot) L.push(two(slot, (it.c === 2 || (it.c === 4 && it.sc >= 1 && it.sc <= 6)) ? esc(sub) : ''));
  if (it.dm) {
    if (it.dm.min != null) {
      L.push(two(`${it.dm.min} - ${it.dm.max} Damage`, `Speed ${it.dm.speed.toFixed(2)}`));
      L.push(`<div>(${it.dm.dps.toFixed(1)} damage per second)</div>`);
    } else L.push(`<div>Adds ${it.dm.dps} damage per second</div>`);
  }
  if (it.ar) L.push(`<div>${it.ar} Armor</div>`);
  sortStats(it.s || []).forEach(s => L.push(statLine(s[0], s[1])));
  if (it.ac) L.push(`<div>Classes: ${esc(classList(it.ac))}</div>`);
  if (it.rl > 1) L.push(`<div>Requires Level ${it.rl}</div>`);
  if (it.rs) L.push(`<div>Requires ${esc(M.skillLines[it.rs[0]] || 'skill ' + it.rs[0])} (${it.rs[1]})</div>`);
  if (it.rep) L.push(`<div>Requires ${esc(it.rep[0])} - ${REP[it.rep[1]] || it.rep[1]}</div>`);
  (it.fx || []).forEach(f => {
    const s = SPELLS[f[1]];
    if (!s) return;
    if (f[0] === 6) { L.push(`<div class="g">Teaches: ${esc(s.n)}${s.r ? ' (' + esc(s.r) + ')' : ''}</div>`); return; }
    const txt = (f[0] === 1 ? (s.ad || s.d) : (s.d || s.ad)) || s.n;
    const cd = f[2] ? ` (${dur(f[2])} Cooldown)` : '';
    L.push(`<div class="g desc">${TRIG[f[0]] || 'Use'}: ${esc(txt)}${cd}</div>`);
  });
  if (it.set && SETS[it.set]) {
    const st = SETS[it.set];
    L.push(`<div class="set"><a href="#/set/${it.set}">${esc(st.n)}</a> (0/${st.items.length})</div>`);
    st.items.forEach(i => L.push(`<div class="setitem">${esc(ITEMS[i] ? ITEMS[i].n : '#' + i)}</div>`));
    st.b.forEach(b => L.push(`<div class="setbonus">(${b[0]}) Set: ${esc(SPELLS[b[1]] ? (SPELLS[b[1]].d || SPELLS[b[1]].ad || SPELLS[b[1]].n) : '')}</div>`));
  }
  if (it.d) L.push(`<div class="d">"${esc(it.d)}"</div>`);
  if (it.sq) L.push('<div class="g">This Item Begins a Quest</div>');
  if (it.st > 1) L.push(`<div>Max Stack: ${it.st}</div>`);
  if (it.sp) L.push(`<div>Sell Price: ${money(it.sp)}</div>`);
  return `<div class="tt">${L.join('')}</div>`;
}
function spellTip(id) {
  const s = SPELLS[id];
  if (!s) return '';
  const L = [two(`<span class="name">${esc(s.n)}</span>`, `<span class="grey">${esc(s.r || '')}</span>`)];
  const cost = s.pw ? (s.pw[1] ? `${s.pw[1]} ${POWER[s.pw[0]] || 'Power'}` : `${num(s.pw[2])}% of base ${POWER[s.pw[0]] || 'mana'}`) : '';
  const rng = s.rg ? `${num(s.rg)} yd range` : '';
  if (cost || rng) L.push(two(cost, rng));
  const cast = s.ct ? `${num(s.ct / 1000)} sec cast` : 'Instant';
  const cd = s.cd ? `${dur(s.cd)} cooldown` : '';
  L.push(two(cast, cd));
  if (s.rg_) L.push(`<div>Reagents: ${s.rg_.map(r => esc(ITEMS[r[0]] ? ITEMS[r[0]].n : '#' + r[0]) + (r[1] > 1 ? ` (${r[1]})` : '')).join(', ')}</div>`);
  if (s.lv) L.push(`<div>Requires Level ${s.lv}</div>`);
  if (s.sk) L.push(`<div>Requires ${esc(M.skillLines[s.sk.sl])} (${s.sk.min})</div>`);
  if (s.d) L.push(`<div class="y desc">${esc(s.d)}</div>`);
  else if (s.ad) L.push(`<div class="y desc">${esc(s.ad)}</div>`);
  if (s.cr) L.push(`<div class="grey">Creates: ${esc(ITEMS[s.cr[0]] ? ITEMS[s.cr[0]].n : '#' + s.cr[0])}${s.cr[1] > 1 ? ' ×' + s.cr[1] : ''}</div>`);
  if (s.en) L.push(`<div class="grey">Enchant: ${esc(s.en[1])}</div>`);
  return `<div class="tt">${L.join('')}</div>`;
}
(function hoverTips() {
  const tip = $('#tip');
  let cur = null;
  function move(e) {
    const w = tip.offsetWidth, h = tip.offsetHeight;
    let x = e.clientX + 16, y = e.clientY + 16;
    if (x + w > innerWidth - 8) x = e.clientX - w - 12;
    if (y + h > innerHeight - 8) y = Math.max(8, innerHeight - h - 8);
    tip.style.left = x + 'px'; tip.style.top = y + 'px';
  }
  document.addEventListener('mouseover', e => {
    const a = e.target.closest && e.target.closest('[data-item],[data-spell]');
    if (!a || a === cur) return;
    cur = a;
    tip.innerHTML = a.dataset.item ? itemTip(a.dataset.item) : spellTip(a.dataset.spell);
    tip.hidden = false;
    move(e);
  });
  document.addEventListener('mousemove', e => { if (cur) move(e); });
  document.addEventListener('mouseout', e => {
    if (cur && !cur.contains(e.relatedTarget)) { cur = null; tip.hidden = true; }
  });
})();

/* ---------------------------------------------------------------- search */
let INDEX = null;
function buildIndex() {
  INDEX = [];
  for (const id in ITEMS) INDEX.push({t: 'item', id, n: ITEMS[id].n, l: ITEMS[id].n.toLowerCase()});
  for (const id in SPELLS) { const s = SPELLS[id]; if (s.n) INDEX.push({t: s.sk ? 'recipe' : 'spell', id, n: s.n + (s.r ? ' (' + s.r + ')' : ''), l: s.n.toLowerCase()}); }
  for (const id in SETS) INDEX.push({t: 'set', id, n: SETS[id].n, l: SETS[id].n.toLowerCase()});
  ZONES.zones.forEach(z => { if (z.n) INDEX.push({t: 'zone', id: z.id, n: z.n, l: z.n.toLowerCase()}); });
  PROFS.forEach(p => INDEX.push({t: 'profession', id: p.id, n: p.n, l: p.n.toLowerCase()}));
}
function search(q, limit) {
  if (!INDEX) buildIndex();
  q = q.trim().toLowerCase();
  if (!q) return [];
  const starts = [], inc = [];
  for (const e of INDEX) {
    const i = e.l.indexOf(q);
    if (i === 0) starts.push(e); else if (i > 0) inc.push(e);
    if (starts.length >= limit) break;
  }
  const order = {profession: 0, recipe: 1, item: 2, set: 3, spell: 4, zone: 5};
  const rank = a => order[a.t];
  starts.sort((a, b) => rank(a) - rank(b) || a.n.localeCompare(b.n));
  inc.sort((a, b) => rank(a) - rank(b) || a.n.localeCompare(b.n));
  return starts.concat(inc).slice(0, limit);
}
function resultLink(e) {
  if (e.t === 'item') return itemLink(e.id);
  if (e.t === 'spell' || e.t === 'recipe') return spellLink(e.id, {rank: true});
  if (e.t === 'set') return `<a href="#/set/${e.id}">${esc(e.n)}</a>`;
  if (e.t === 'zone') return `<a href="#/zone/${e.id}">${esc(e.n)}</a>`;
  return `<a href="#/profession/${e.id}">${esc(e.n)}</a>`;
}
(function searchBox() {
  const q = $('#q'), res = $('#qres');
  let timer = null, sel = -1;
  function show() {
    const r = search(q.value, 25);
    sel = -1;
    if (!r.length) { res.hidden = true; return; }
    res.innerHTML = r.map(e => `${resultLink(e).replace('<a ', '<a class="res" ')}`).join('');
    res.querySelectorAll('a').forEach(a => a.insertAdjacentHTML('beforeend', `<span class="kind">${r[[...res.children].indexOf(a)].t}</span>`));
    res.hidden = false;
  }
  q.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(show, 120); });
  q.addEventListener('keydown', e => {
    const items = [...res.querySelectorAll('a')];
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      sel = Math.max(0, Math.min(items.length - 1, sel + (e.key === 'ArrowDown' ? 1 : -1)));
      items.forEach((a, i) => a.classList.toggle('sel', i === sel));
      if (items[sel]) items[sel].scrollIntoView({block: 'nearest'});
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (sel >= 0 && items[sel]) location.hash = items[sel].getAttribute('href');
      else location.hash = '#/search?q=' + encodeURIComponent(q.value);
      res.hidden = true;
    } else if (e.key === 'Escape') res.hidden = true;
  });
  document.addEventListener('click', e => { if (!e.target.closest('.search')) res.hidden = true; });
  res.addEventListener('click', () => { res.hidden = true; });
})();

/* ---------------------------------------------------------------- tables */
const SORT = {};
function table(key, cols, rows, opts) {
  opts = opts || {};
  const st = SORT[key] || (SORT[key] = {c: opts.sort || 0, d: opts.dir || 1});
  const col = cols[st.c];
  const sorted = rows.slice();
  if (col && col.s) sorted.sort((a, b) => { const x = col.s(a), y = col.s(b); return (x < y ? -1 : x > y ? 1 : 0) * st.d; });
  const lim = opts.limit || 300;
  const shown = sorted.slice(0, lim);
  let h = `<table data-tkey="${key}"><thead><tr>${cols.map((c, i) => `<th data-i="${i}" class="${i === st.c ? (st.d > 0 ? 's-asc' : 's-desc') : ''}">${c.h}</th>`).join('')}</tr></thead><tbody>`;
  h += shown.map(r => `<tr>${cols.map(c => `<td class="${c.num ? 'num' : ''}">${c.r(r)}</td>`).join('')}</tr>`).join('');
  h += '</tbody></table>';
  if (sorted.length > lim) h += `<p class="muted">Showing ${lim} of ${sorted.length}. <a href="#" data-more="${key}">Show all</a></p>`;
  return h;
}
document.addEventListener('click', e => {
  const th = e.target.closest('th[data-i]');
  if (th) {
    const key = th.closest('table').dataset.tkey, st = SORT[key], i = +th.dataset.i;
    if (st.c === i) st.d = -st.d; else { st.c = i; st.d = 1; }
    render();
    return;
  }
  const more = e.target.closest('a[data-more]');
  if (more) { e.preventDefault(); LIMITS[more.dataset.more] = 1e9; render(); }
});
const LIMITS = {};

/* ---------------------------------------------------------------- pages */
const STATE = {items: {q: '', c: '', sc: '', qmin: '', lmin: '', lmax: '', flag: ''}, prof: {q: '', skill: '', flag: '', hideGrey: false}, cls: {id: 0}};

function pageHome() {
  const c = M.counts;
  return `<h1>WoW Forever reference</h1>
  <p>Client data from build <b>${M.build}</b>, decoded via wago.tools, compared against Classic Era <b>${M.eraBuild}</b>. Generated ${M.generated}.</p>
  <div class="tiles">
    <a class="tile" href="#/professions"><div><b>Professions</b><div class="sub">${c.recipes} recipes, ${c.newRecipes} new in Forever</div></div></a>
    <a class="tile" href="#/items"><div><b>Items</b><div class="sub">${c.items} items, ${c.newItems} new, ${c.modItems} changed</div></div></a>
    <a class="tile" href="#/classes"><div><b>Class abilities</b><div class="sub">${c.spells} spells, ${c.newSpells} new</div></div></a>
    <a class="tile" href="#/sets"><div><b>Item sets</b><div class="sub">${c.sets} sets</div></div></a>
    <a class="tile" href="#/zones"><div><b>Zones</b><div class="sub">${c.zones} areas</div></div></a>
    <a class="tile" href="#/new"><div><b>What's new</b><div class="sub">Diff against Classic Era</div></div></a>
  </div>
  <h2>What this covers</h2>
  <p>Everything here is read from the game client's database tables: items with computed stats, armor and damage; spells and their tooltip text; profession recipes with reagents, skill thresholds and the recipe items that teach them; item sets; zones.</p>
  <p class="muted">Not in the client, so not here: quest text and objectives, NPC locations, drop rates, vendor stock, trainer lists. Recipe sources that are not a recipe item are marked as trainer/quest without further detail. Icons load from Wowhead's CDN and may be missing for brand-new art.</p>`;
}

function pageProfessions() {
  const isRecipe = s => SPELLS[s].cr || SPELLS[s].en || SPELLS[s].rg_;
  const kind = k => PROFS.filter(p => p.kind === k).map(p => {
    const n = p.recipes.filter(s => SPELLS[s].sk.new && isRecipe(s)).length;
    return `<a class="tile" href="#/profession/${p.id}">${icon(p.ic, 'large')}<div><b>${esc(p.n)}</b><div class="sub">${p.recipes.length} recipes${n ? `, <span class="badge new">${n} NEW</span>` : ''}</div></div></a>`;
  }).join('');
  return `<h1>Professions</h1><h2>Primary</h2><div class="tiles">${kind('primary')}</div><h2>Secondary</h2><div class="tiles">${kind('secondary')}</div><h2>Other</h2><div class="tiles">${kind('other')}</div>`;
}

function skillCell(sk, mine) {
  if (!sk.lo && !sk.hi) return sk.req ? `<span class="sk-o"><b>${sk.req}</b></span>` : '<span class="muted">–</span>';
  const mid = Math.floor((sk.lo + sk.hi) / 2);
  const req = sk.req || 0;
  const cls = mine ? ((req && mine < req) ? 'sk-x' : mine < sk.lo ? 'sk-o' : mine < mid ? 'sk-y' : mine < sk.hi ? 'sk-g' : 'sk-x') : 'sk-o';
  const reqTxt = req ? `<b>${req}</b>` : `<span title="Learn-at skill is not in the client data for trainer-taught recipes">?</span>`;
  return `<span class="${cls}">${reqTxt}</span> <span class="muted small"><span class="sk-y">${sk.lo}</span> / <span class="sk-g">${mid}</span> / <span class="sk-x">${sk.hi}</span></span>`;
}
function recipeSource(s) {
  if (s.tb && s.tb.length) return s.tb.map(i => itemLink(i)).join('<br>');
  if (s.sk.acq === 1) return '<span class="muted">Learned with profession</span>';
  return '<span class="muted" title="Trainer lists and quest rewards are server-side and not in the client data">Trainer / quest</span>';
}
function pageProfession(id, params) {
  const p = PROFS.find(x => x.id === +id);
  if (!p) return '<h1>Unknown profession</h1>';
  const st = STATE.prof;
  if (params.new) st.flag = 'new';
  const mine = +st.skill || 0;
  const catPath = c => { const path = []; let guard = 0; while (c && p.cats[c] && guard++ < 6) { path.unshift(p.cats[c]); c = p.cats[c].p; } return path; };
  const rows = p.recipes.map(s => ({id: s, s: SPELLS[s]})).filter(r => {
    if (st.q && !r.s.n.toLowerCase().includes(st.q.toLowerCase()) && !(r.s.cr && ITEMS[r.s.cr[0]] && ITEMS[r.s.cr[0]].n.toLowerCase().includes(st.q.toLowerCase()))) return false;
    if (st.flag === 'new' && !r.s.sk.new) return false;
    if (st.flag === 'chg' && !r.s.sk.chg) return false;
    if (st.hideGrey && mine && mine >= r.s.sk.hi) return false;
    return true;
  });
  const recipes = rows.filter(r => r.s.cr || r.s.en || r.s.rg_), other = rows.filter(r => !(r.s.cr || r.s.en || r.s.rg_));
  const groups = new Map();
  recipes.forEach(r => {
    const path = catPath(r.s.sk.cat);
    const key = path.map(c => c.n).join(' › ') || 'Uncategorized';
    const ord = path.map(c => String(c.o).padStart(4, '0')).join('.');
    if (!groups.has(key)) groups.set(key, {ord, rows: []});
    groups.get(key).rows.push(r);
  });
  const cols = [
    {h: 'Recipe', r: r => spellLink(r.id, {badges: true}) + (r.s.sk.chg ? `<div class="chg">${esc(r.s.sk.chg.join('; '))}</div>` : ''), s: r => r.s.n},
    {h: 'Creates', r: r => r.s.cr ? itemLink(r.s.cr[0], {count: r.s.cr[1]}) : (r.s.en ? `<span class="muted">${esc(r.s.en[1])}</span>` : ''), s: r => r.s.cr ? (ITEMS[r.s.cr[0]] || {}).n || '' : ''},
    {h: 'Reagents', r: r => (r.s.rg_ || []).map(g => `<span class="reag">${itemLink(g[0], {count: g[1]})}</span>`).join(' ')},
    {h: 'Skill', r: r => skillCell(r.s.sk, mine), s: r => r.s.sk.min, num: true},
    {h: 'Source', r: r => recipeSource(r.s)},
  ];
  let h = `<h1>${icon(p.ic, 'large')}${esc(p.n)}</h1>
  <div class="filters">
    <input id="pf-q" placeholder="Filter recipes" value="${esc(st.q)}">
    <label>My skill <input id="pf-skill" type="number" min="0" max="450" style="width:70px" value="${esc(st.skill)}"></label>
    <label><input id="pf-grey" type="checkbox" ${st.hideGrey ? 'checked' : ''}> hide grey</label>
    <select id="pf-flag"><option value="">All recipes</option><option value="new" ${st.flag === 'new' ? 'selected' : ''}>New in Forever</option><option value="chg" ${st.flag === 'chg' ? 'selected' : ''}>Changed vs Classic Era</option></select>
    <span class="muted small">${recipes.length} recipes</span>
    <a class="ext" href="${WH}skills/${p.n.toLowerCase().replace(/ /g, '-')}" target="_blank">Wowhead Forever ↗</a>
  </div>`;
  const keys = [...groups.keys()].sort((a, b) => groups.get(a).ord.localeCompare(groups.get(b).ord));
  h += '<table><thead><tr>' + cols.map(c => `<th>${c.h}</th>`).join('') + '</tr></thead><tbody>';
  keys.forEach(k => {
    const g = groups.get(k);
    g.rows.sort((a, b) => a.s.sk.min - b.s.sk.min || a.s.n.localeCompare(b.s.n));
    h += `<tr class="cat"><td colspan="${cols.length}">${esc(k)} <span class="muted small">(${g.rows.length})</span></td></tr>`;
    h += g.rows.map(r => `<tr>${cols.map(c => `<td class="${c.num ? 'num' : ''}">${c.r(r)}</td>`).join('')}</tr>`).join('');
  });
  h += '</tbody></table>';
  if (other.length) h += `<h2>Skill ranks and passives</h2><p>${other.map(r => spellLink(r.id, {rank: true, badges: true}) + ` <span class="muted small">(${r.s.sk.min})</span>`).join(' &nbsp;·&nbsp; ')}</p>`;
  return h;
}
function bindProfession() {
  const st = STATE.prof;
  const q = $('#pf-q'); if (!q) return;
  q.addEventListener('input', () => { st.q = q.value; rerenderKeepFocus('#pf-q'); });
  $('#pf-skill').addEventListener('input', e => { st.skill = e.target.value; rerenderKeepFocus('#pf-skill'); });
  $('#pf-grey').addEventListener('change', e => { st.hideGrey = e.target.checked; render(); });
  $('#pf-flag').addEventListener('change', e => { st.flag = e.target.value; render(); });
}
function rerenderKeepFocus(sel) {
  const el = $(sel), pos = el && el.selectionStart;
  render();
  const n = $(sel);
  if (n) { n.focus(); try { n.setSelectionRange(pos, pos); } catch (e) { /* number inputs */ } }
}

function pageItem(id) {
  const it = ITEMS[id];
  if (!it) return `<h1>Unknown item</h1><p><a class="ext" href="${WH}item=${id}" target="_blank">Look it up on Wowhead Forever ↗</a></p>`;
  let side = '';
  const list = (title, ids, fn) => ids && ids.length ? `<h3>${title}</h3><ul>${ids.map(i => `<li>${fn(i)}</li>`).join('')}</ul>` : '';
  side += list('Created by', it.cb, s => spellLink(s, {badges: true}) + (SPELLS[s].sk ? ` <span class="muted small">${esc(M.skillLines[SPELLS[s].sk.sl])} ${SPELLS[s].sk.min}</span>` : ''));
  side += list('Reagent for', it.rf, s => spellLink(s, {badges: true}) + (SPELLS[s].sk ? ` <span class="muted small">${esc(M.skillLines[SPELLS[s].sk.sl])} ${SPELLS[s].sk.min}</span>` : ''));
  const teaches = (it.fx || []).filter(f => f[0] === 6).map(f => f[1]);
  side += list('Teaches', teaches, s => spellLink(s, {badges: true}));
  const uses = (it.fx || []).filter(f => f[0] !== 6).map(f => f[1]);
  side += list('Spell effects', uses, s => spellLink(s, {rank: true}));
  if (it.set) side += `<h3>Item set</h3><p><a href="#/set/${it.set}">${esc(SETS[it.set].n)}</a></p>`;
  if (it.mod) side += `<h3>Changed vs Classic Era</h3><p class="chg">${esc(it.mod.join(', '))}${it.old ? `<br>Classic Era name: ${esc(it.old)}` : ''}</p>`;
  return `<h1>${icon(it.ic, 'large')}${esc(it.n)}${badges(it)}</h1>
  <p class="muted">${esc(M.itemClasses[it.c] || '')} › ${esc(subName(it.c, it.sc))}${it.it ? ' › ' + M.invTypes[it.it] : ''} &nbsp; item #${id} &nbsp; <a class="ext" href="${WH}item=${id}" target="_blank">Wowhead Forever ↗</a></p>
  <div class="row"><div class="detail">${itemTip(id, true)}</div><div class="col">${side || '<p class="muted">No related recipes.</p>'}</div></div>`;
}

function pageItems() {
  const st = STATE.items;
  const subs = st.c !== '' ? Object.keys(M.itemSubClasses).filter(k => k.startsWith(st.c + '_')).map(k => [k.split('_')[1], M.itemSubClasses[k]]) : [];
  const q = st.q.toLowerCase();
  const rows = [];
  for (const id in ITEMS) {
    const it = ITEMS[id];
    if (st.c !== '' && it.c !== +st.c) continue;
    if (st.sc !== '' && it.sc !== +st.sc) continue;
    if (st.qmin !== '' && it.q < +st.qmin) continue;
    if (st.lmin !== '' && (it.rl || 0) < +st.lmin) continue;
    if (st.lmax !== '' && (it.rl || 0) > +st.lmax) continue;
    if (st.flag === 'new' && !it.new) continue;
    if (st.flag === 'mod' && !it.mod) continue;
    if (q && !it.n.toLowerCase().includes(q)) continue;
    rows.push({id, it});
  }
  const cols = [
    {h: 'Name', r: r => itemLink(r.id, {badges: true}) + (r.it.old ? `<div class="muted small">was: ${esc(r.it.old)}</div>` : ''), s: r => r.it.n},
    {h: 'Type', r: r => esc(subName(r.it.c, r.it.sc)), s: r => subName(r.it.c, r.it.sc)},
    {h: 'Slot', r: r => M.invTypes[r.it.it] || '', s: r => M.invTypes[r.it.it] || ''},
    {h: 'Level', r: r => r.it.il, s: r => r.it.il, num: true},
    {h: 'Req', r: r => r.it.rl || '', s: r => r.it.rl || 0, num: true},
    {h: 'Quality', r: r => `<span class="q${r.it.q}">${QNAME[r.it.q]}</span>`, s: r => r.it.q},
    {h: 'Sell', r: r => money(r.it.sp), s: r => r.it.sp || 0, num: true},
  ];
  const opt = (v, t, cur) => `<option value="${v}" ${String(cur) === String(v) ? 'selected' : ''}>${esc(t)}</option>`;
  let h = `<h1>Items</h1><div class="filters">
    <input id="if-q" placeholder="Name contains" value="${esc(st.q)}">
    <select id="if-c">${opt('', 'Any class', st.c)}${Object.keys(M.itemClasses).map(c => opt(c, M.itemClasses[c], st.c)).join('')}</select>
    <select id="if-sc" ${subs.length ? '' : 'disabled'}>${opt('', 'Any subclass', st.sc)}${subs.map(s => opt(s[0], s[1], st.sc)).join('')}</select>
    <select id="if-q">${opt('', 'Any quality', st.qmin)}${QNAME.map((n, i) => opt(i, n + '+', st.qmin)).join('')}</select>
    <label>Req level <input id="if-lmin" type="number" style="width:60px" value="${esc(st.lmin)}"> – <input id="if-lmax" type="number" style="width:60px" value="${esc(st.lmax)}"></label>
    <select id="if-flag">${opt('', 'All items', st.flag)}${opt('new', 'New in Forever', st.flag)}${opt('mod', 'Changed vs Classic Era', st.flag)}</select>
    <span class="muted small">${rows.length} items</span></div>`;
  h += table('items', cols, rows, {limit: LIMITS.items || 200});
  return h;
}
function bindItems() {
  const st = STATE.items;
  const q = $('#if-q'); if (!q) return;
  q.addEventListener('input', () => { st.q = q.value; rerenderKeepFocus('#if-q'); });
  $('#if-c').addEventListener('change', e => { st.c = e.target.value; st.sc = ''; render(); });
  $('#if-sc').addEventListener('change', e => { st.sc = e.target.value; render(); });
  $('#if-q').addEventListener('change', e => { st.qmin = e.target.value; render(); });
  $('#if-lmin').addEventListener('input', e => { st.lmin = e.target.value; rerenderKeepFocus('#if-lmin'); });
  $('#if-lmax').addEventListener('input', e => { st.lmax = e.target.value; rerenderKeepFocus('#if-lmax'); });
  $('#if-flag').addEventListener('change', e => { st.flag = e.target.value; render(); });
}

function pageSpell(id) {
  const s = SPELLS[id];
  if (!s) return `<h1>Unknown spell</h1><p><a class="ext" href="${WH}spell=${id}" target="_blank">Look it up on Wowhead Forever ↗</a></p>`;
  let side = '';
  if (s.sk) {
    const p = PROFS.find(x => x.id === s.sk.sl);
    const cat = p && p.cats[s.sk.cat] ? p.cats[s.sk.cat].n : '';
    side += `<h3>Recipe</h3><p><a href="#/profession/${s.sk.sl}">${esc(M.skillLines[s.sk.sl])}</a>${cat ? ' › ' + esc(cat) : ''}<br>Skill: ${skillCell(s.sk)}<br>Source: ${recipeSource(s)}</p>`;
    if (s.sk.chg) side += `<p class="chg">Changed vs Classic Era: ${esc(s.sk.chg.join('; '))}</p>`;
    if (s.sk.sup) side += `<p class="muted small">Replaces ${spellLink(s.sk.sup, {rank: true})}</p>`;
  }
  if (s.cr) side += `<h3>Creates</h3><p>${itemLink(s.cr[0], {count: s.cr[1], badges: true})}</p>`;
  if (s.rg_) side += `<h3>Reagents</h3><ul>${s.rg_.map(g => `<li>${itemLink(g[0], {count: g[1]})}</li>`).join('')}</ul>`;
  if (s.en) side += `<h3>Enchantment</h3><p>${esc(s.en[1])} <span class="muted small">#${s.en[0]}</span></p>`;
  if (s.ls) side += `<h3>Teaches spell</h3><p>${spellLink(s.ls, {rank: true})}</p>`;
  if (s.tb) side += `<h3>Taught by</h3><ul>${s.tb.map(i => `<li>${itemLink(i, {badges: true})}</li>`).join('')}</ul>`;
  if (s.ub) side += `<h3>Used by items</h3><ul>${s.ub.slice(0, 60).map(i => `<li>${itemLink(i)}</li>`).join('')}${s.ub.length > 60 ? `<li class="muted">…and ${s.ub.length - 60} more</li>` : ''}</ul>`;
  if (s.cl) side += `<h3>Skill lines</h3><p>${s.cl.map(l => esc(M.skillLines[l] || l)).join(', ')}</p>`;
  if (s.ad && s.d) side += `<h3>Aura text</h3><p>${esc(s.ad)}</p>`;
  return `<h1>${icon(s.ic, 'large')}${esc(s.n)}${s.r ? ` <span class="muted">${esc(s.r)}</span>` : ''}${badges(s.sk || s)}</h1>
  <p class="muted">spell #${id} &nbsp; <a class="ext" href="${WH}spell=${id}" target="_blank">Wowhead Forever ↗</a></p>
  <div class="row"><div class="detail">${spellTip(id)}</div><div class="col">${side}</div></div>`;
}

function pageClasses() {
  return `<h1>Class abilities</h1><div class="tiles">${CLS.classes.map(c => {
    const n = c.lines.reduce((a, l) => a + l.spells.length, 0), nw = c.lines.reduce((a, l) => a + l.spells.filter(s => SPELLS[s].new).length, 0);
    return `<a class="tile" href="#/class/${c.id}"><div><b>${esc(c.n)}</b><div class="sub">${n} spells${nw ? `, <span class="badge new">${nw} NEW</span>` : ''}</div></div></a>`;
  }).join('')}</div>
  <h2>General lines</h2><div class="tiles">${CLS.general.map(l => `<a class="tile" href="#/line/${l.id}"><div><b>${esc(l.n)}</b><div class="sub">${l.spells.length} spells</div></div></a>`).join('')}</div>`;
}
function spellTable(key, ids) {
  const rows = ids.map(id => ({id, s: SPELLS[id]}));
  const cols = [
    {h: 'Spell', r: r => spellLink(r.id, {rank: true, badges: true}), s: r => r.s.n},
    {h: 'Level', r: r => r.s.lv || '', s: r => r.s.lv || 0, num: true},
    {h: 'Cost', r: r => r.s.pw ? (r.s.pw[1] ? `${r.s.pw[1]} ${POWER[r.s.pw[0]] || ''}` : `${num(r.s.pw[2])}%`) : '', s: r => r.s.pw ? r.s.pw[1] : 0, num: true},
    {h: 'Cast', r: r => r.s.ct ? num(r.s.ct / 1000) + 's' : 'Instant', s: r => r.s.ct || 0, num: true},
    {h: 'Cooldown', r: r => r.s.cd ? dur(r.s.cd) : '', s: r => r.s.cd || 0, num: true},
    {h: 'Description', r: r => `<span class="small">${esc((r.s.d || r.s.ad || '').slice(0, 220))}</span>`},
  ];
  return table(key, cols, rows, {sort: 1, limit: LIMITS[key] || 400});
}
function pageClass(id) {
  const c = CLS.classes.find(x => x.id === +id);
  if (!c) return '<h1>Unknown class</h1>';
  const st = STATE.cls;
  if (st.id !== c.id) { STATE.cls = {id: c.id, lmin: '', lmax: '', q: '', off: new Set(c.lines.filter(l => /engraving/i.test(l.n)).map(l => l.id)), group: true, flag: ''}; }
  const s = STATE.cls;
  const q = s.q.toLowerCase();
  const rows = [];
  c.lines.forEach(l => {
    if (s.off.has(l.id)) return;
    l.spells.forEach(sid => {
      const sp = SPELLS[sid];
      const lv = sp.lv || 0;
      if (s.lmin !== '' && lv < +s.lmin) return;
      if (s.lmax !== '' && lv > +s.lmax) return;
      if (s.flag === 'new' && !sp.new) return;
      if (q && !sp.n.toLowerCase().includes(q)) return;
      rows.push({id: sid, s: sp, line: l, lv});
    });
  });
  rows.sort((a, b) => a.lv - b.lv || a.s.n.localeCompare(b.s.n) || (a.s.r || '').localeCompare(b.s.r || '', undefined, {numeric: true}));
  const cols = [
    {h: 'Level', r: r => r.lv || '<span class="muted">–</span>'},
    {h: 'Spell', r: r => spellLink(r.id, {rank: true, badges: true})},
    {h: 'Line', r: r => `<span class="muted">${esc(r.line.n)}</span>`},
    {h: 'Cost', r: r => r.s.pw ? (r.s.pw[1] ? `${r.s.pw[1]} ${POWER[r.s.pw[0]] || ''}` : `${num(r.s.pw[2])}%`) : ''},
    {h: 'Cast', r: r => r.s.ct ? num(r.s.ct / 1000) + 's' : 'Instant'},
    {h: 'Cooldown', r: r => r.s.cd ? dur(r.s.cd) : ''},
    {h: 'Description', r: r => `<span class="small">${esc((r.s.d || r.s.ad || '').slice(0, 200))}</span>`},
  ];
  let h = `<h1>${esc(c.n)}</h1>
  <div class="filters">
    <input id="cf-q" placeholder="Filter spells" value="${esc(s.q)}">
    <label>Level <input id="cf-lmin" type="number" min="1" max="60" style="width:60px" value="${esc(s.lmin)}"> – <input id="cf-lmax" type="number" min="1" max="60" style="width:60px" value="${esc(s.lmax)}"></label>
    <label><input id="cf-group" type="checkbox" ${s.group ? 'checked' : ''}> group by level</label>
    <select id="cf-flag"><option value="">All spells</option><option value="new" ${s.flag === 'new' ? 'selected' : ''}>New in Forever</option></select>
    <span class="muted small">${rows.length} spells</span>
  </div>
  <div class="tabs">${c.lines.map(l => `<a href="#" data-line="${l.id}" class="${s.off.has(l.id) ? '' : 'on'}">${esc(l.n)} <span class="muted small">${l.spells.length}</span></a>`).join('')}</div>
  <p class="muted small">Sorted by the level a rank becomes available: the levels with entries are the ones where a trainer visit pays off.</p>`;
  h += '<table><thead><tr>' + cols.map(x => `<th>${x.h}</th>`).join('') + '</tr></thead><tbody>';
  let last = null;
  rows.forEach(r => {
    if (s.group && r.lv !== last) {
      last = r.lv;
      const n = rows.filter(x => x.lv === r.lv).length;
      h += `<tr class="cat"><td colspan="${cols.length}">${r.lv ? 'Level ' + r.lv : 'No level requirement'} <span class="muted small">(${n})</span></td></tr>`;
    }
    h += `<tr>${cols.map(x => `<td>${x.r(r)}</td>`).join('')}</tr>`;
  });
  h += '</tbody></table>';
  return h;
}
function bindClass() {
  const s = STATE.cls;
  const q = $('#cf-q'); if (!q) return;
  q.addEventListener('input', () => { s.q = q.value; rerenderKeepFocus('#cf-q'); });
  $('#cf-lmin').addEventListener('input', e => { s.lmin = e.target.value; rerenderKeepFocus('#cf-lmin'); });
  $('#cf-lmax').addEventListener('input', e => { s.lmax = e.target.value; rerenderKeepFocus('#cf-lmax'); });
  $('#cf-group').addEventListener('change', e => { s.group = e.target.checked; render(); });
  $('#cf-flag').addEventListener('change', e => { s.flag = e.target.value; render(); });
  document.querySelectorAll('a[data-line]').forEach(a => a.addEventListener('click', e => {
    e.preventDefault();
    const id = +a.dataset.line;
    if (s.off.has(id)) s.off.delete(id); else s.off.add(id);
    render();
  }));
}
function pageLine(id) {
  const l = CLS.general.find(x => x.id === +id);
  if (!l) return '<h1>Unknown skill line</h1>';
  return `<h1>${esc(l.n)}</h1>${spellTable('line' + id, l.spells)}`;
}

function pageSets() {
  const rows = Object.keys(SETS).map(id => ({id, s: SETS[id]}));
  const cols = [
    {h: 'Set', r: r => `<a href="#/set/${r.id}">${esc(r.s.n)}</a>`, s: r => r.s.n},
    {h: 'Pieces', r: r => r.s.items.length, s: r => r.s.items.length, num: true},
    {h: 'Items', r: r => r.s.items.map(i => itemLink(i, {noicon: true})).join(', ')},
  ];
  return `<h1>Item sets</h1>${table('sets', cols, rows)}`;
}
function pageSet(id) {
  const s = SETS[id];
  if (!s) return '<h1>Unknown set</h1>';
  return `<h1>${esc(s.n)}</h1>${s.rs ? `<p>Requires ${esc(M.skillLines[s.rs[0]])} (${s.rs[1]})</p>` : ''}
  <div class="row"><div class="col"><h3>Pieces</h3><ul>${s.items.map(i => `<li>${itemLink(i, {badges: true})} <span class="muted small">${ITEMS[i] ? M.invTypes[ITEMS[i].it] : ''}</span></li>`).join('')}</ul></div>
  <div class="col"><h3>Set bonuses</h3><ul>${s.b.map(b => `<li><b>(${b[0]})</b> ${esc(SPELLS[b[1]] ? (SPELLS[b[1]].d || SPELLS[b[1]].ad || SPELLS[b[1]].n) : '#' + b[1])}</li>`).join('') || '<li class="muted">none</li>'}</ul></div></div>`;
}

function pageZones() {
  const byMap = new Map();
  ZONES.zones.filter(z => !z.p && z.n).forEach(z => { if (!byMap.has(z.m)) byMap.set(z.m, []); byMap.get(z.m).push(z); });
  const kids = new Map();
  ZONES.zones.forEach(z => { if (z.p) { if (!kids.has(z.p)) kids.set(z.p, 0); kids.set(z.p, kids.get(z.p) + 1); } });
  const maps = [...byMap.keys()].sort((a, b) => (ZONES.maps[a] || {}).t - (ZONES.maps[b] || {}).t || a - b);
  return `<h1>Zones</h1><p class="muted">Area names from the client's map tables, grouped by continent or instance. Level ranges are server-side and not available.</p>` +
    maps.map(m => `<div class="zones"><h2>${esc((ZONES.maps[m] || {}).n || 'Map ' + m)}</h2><ul>${byMap.get(m).sort((a, b) => a.n.localeCompare(b.n)).map(z => `<li><a href="#/zone/${z.id}">${esc(z.n)}</a>${kids.get(z.id) ? ` <span class="muted small">${kids.get(z.id)} areas</span>` : ''}</li>`).join('')}</ul></div>`).join('');
}
function pageZone(id) {
  const z = ZONES.zones.find(x => x.id === +id);
  if (!z) return '<h1>Unknown zone</h1>';
  const parent = z.p ? ZONES.zones.find(x => x.id === z.p) : null;
  const kids = ZONES.zones.filter(x => x.p === z.id).sort((a, b) => a.n.localeCompare(b.n));
  const mapId = MAP_BY_AREA[z.id] || (parent && MAP_BY_AREA[parent.id]);
  return `<h1>${esc(z.n)}</h1><p class="muted">${esc((ZONES.maps[z.m] || {}).n || '')}${parent ? ` › <a href="#/zone/${parent.id}">${esc(parent.n)}</a>` : ''} &nbsp; area #${z.id} &nbsp; <a class="ext" href="${WH}zone=${z.id}" target="_blank">Wowhead Forever ↗</a></p>
  ${mapId ? mapImage(mapId) : ''}
  ${kids.length ? `<div class="zones"><h2>Subzones</h2><ul>${kids.map(k => `<li><a href="#/zone/${k.id}">${esc(k.n)}</a></li>`).join('')}</ul></div>` : ''}`;
}

function pageNew() {
  const isRecipe = s => SPELLS[s].cr || SPELLS[s].en || SPELLS[s].rg_;
  const profRows = PROFS.map(p => ({p, n: p.recipes.filter(s => SPELLS[s].sk.new && isRecipe(s)).length, c: p.recipes.filter(s => SPELLS[s].sk.chg && isRecipe(s)).length})).filter(r => r.n || r.c);
  const newItems = Object.keys(ITEMS).filter(id => ITEMS[id].new);
  const byClass = new Map();
  newItems.forEach(id => { const k = subName(ITEMS[id].c, ITEMS[id].sc); if (!byClass.has(k)) byClass.set(k, []); byClass.get(k).push(id); });
  const classRows = CLS.classes.map(c => ({c, ids: c.lines.flatMap(l => l.spells.filter(s => SPELLS[s].new))})).filter(r => r.ids.length);
  return `<h1>What's new in Forever</h1><p class="muted">Compared with Classic Era build ${M.eraBuild}. "New" means the ID does not exist in Classic Era; "changed" means the computed values differ.</p>
  <h2>Recipes</h2><table><thead><tr><th>Profession</th><th>New</th><th>Changed</th></tr></thead><tbody>${profRows.map(r => `<tr><td><a href="#/profession/${r.p.id}">${icon(r.p.ic)}${esc(r.p.n)}</a></td><td class="num"><a href="#/profession/${r.p.id}?new=1">${r.n}</a></td><td class="num">${r.c}</td></tr>`).join('')}</tbody></table>
  <h2>New class abilities</h2>${classRows.map(r => {
    const byName = new Map();
    r.ids.forEach(s => { const n = SPELLS[s].n; if (!byName.has(n)) byName.set(n, []); byName.get(n).push(s); });
    const parts = [...byName.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([n, ids]) => spellLink(ids[0], {noicon: true}) + (ids.length > 1 ? ` <span class="muted small">×${ids.length}</span>` : ''));
    return `<h3><a href="#/class/${r.c.id}">${esc(r.c.n)}</a> <span class="muted small">${byName.size} spells, ${r.ids.length} ranks</span></h3><p>${parts.join(' &nbsp;·&nbsp; ')}</p>`;
  }).join('')}
  <h2>New items by type <span class="muted small">(${newItems.length})</span></h2><table><thead><tr><th>Type</th><th>Count</th><th>Examples</th></tr></thead><tbody>${[...byClass.entries()].sort((a, b) => b[1].length - a[1].length).map(([k, ids]) => `<tr><td>${esc(k)}</td><td class="num">${ids.length}</td><td>${ids.slice(0, 6).map(i => itemLink(i, {noicon: true})).join(', ')}${ids.length > 6 ? ', …' : ''}</td></tr>`).join('')}</tbody></table>
  <p><a href="#/items?flag=new">Browse all new items</a> · <a href="#/items?flag=mod">Browse changed items</a></p>`;
}

/* ---------------------------------------------------------------- maps */
const MAPS = (window.FR_MAPS || {maps: {}}).maps;
const MAP_BY_AREA = {};
Object.keys(MAPS).forEach(id => { if (MAPS[id].area) MAP_BY_AREA[MAPS[id].area] = +id; });
function mapImage(id, opts) {
  const m = MAPS[id];
  if (!m || !m.img) return '';
  opts = opts || {};
  const kids = (m.kids || []).filter(k => MAPS[k[0]]);
  return `<div class="mapwrap" style="max-width:${m.w}px"><img src="maps/${id}.jpg" width="${m.w}" height="${m.h}" alt="${esc(m.n)}">
    ${kids.map(k => `<a class="maprect" href="#/map/${k[0]}" title="${esc(MAPS[k[0]].n)}" style="left:${(k[1] * 100).toFixed(2)}%;top:${(k[2] * 100).toFixed(2)}%;width:${((k[3] - k[1]) * 100).toFixed(2)}%;height:${((k[4] - k[2]) * 100).toFixed(2)}%"><span>${esc(MAPS[k[0]].n)}</span></a>`).join('')}</div>`;
}
function pageMaps() {
  const roots = Object.keys(MAPS).filter(id => !MAPS[id].p).map(Number);
  const tree = (id, depth) => {
    const kids = Object.keys(MAPS).filter(k => MAPS[k].p === id).map(Number).sort((a, b) => MAPS[a].n.localeCompare(MAPS[b].n));
    return `<li><a href="#/map/${id}">${esc(MAPS[id].n)}</a>${MAPS[id].img ? '' : ' <span class="muted small">(no image)</span>'}${kids.length && depth < 3 ? `<ul>${kids.map(k => tree(k, depth + 1)).join('')}</ul>` : ''}</li>`;
  };
  return `<h1>Maps</h1><p class="muted">World map art from the client's UiMap tables, stitched from the original tiles. Click a zone outline to open it.</p>
  ${mapImage(947)}<div class="zones"><ul>${roots.map(r => tree(r, 0)).join('')}</ul></div>`;
}
function pageMap(id) {
  const m = MAPS[id];
  if (!m) return '<h1>Unknown map</h1>';
  const crumbs = [];
  let p = m.p;
  while (p && MAPS[p] && crumbs.length < 5) { crumbs.unshift(`<a href="#/map/${p}">${esc(MAPS[p].n)}</a>`); p = MAPS[p].p; }
  const kids = Object.keys(MAPS).filter(k => MAPS[k].p === +id).map(Number).sort((a, b) => MAPS[a].n.localeCompare(MAPS[b].n));
  const subs = m.area ? ZONES.zones.filter(z => z.p === m.area).sort((a, b) => a.n.localeCompare(b.n)) : [];
  return `<h1>${esc(m.n)}</h1><p class="muted">${crumbs.join(' › ')}${crumbs.length ? ' › ' : ''}${esc(m.n)} &nbsp; map #${id}${m.area ? ` &nbsp; <a href="#/zone/${m.area}">area #${m.area}</a>` : ''}</p>
  ${mapImage(id) || '<p class="muted">No map art in the client for this map.</p>'}
  <div class="row">${kids.length ? `<div class="col"><h3>Maps within</h3><ul>${kids.map(k => `<li><a href="#/map/${k}">${esc(MAPS[k].n)}</a></li>`).join('')}</ul></div>` : ''}
  ${subs.length ? `<div class="col zones"><h3>Subzones</h3><ul>${subs.map(z => `<li><a href="#/zone/${z.id}">${esc(z.n)}</a></li>`).join('')}</ul></div>` : ''}</div>`;
}

const PATCHES = window.FR_PATCHES || [];
const FIELD_NAMES = {n: 'name', q: 'quality', il: 'item level', rl: 'required level', b: 'binding', mc: 'unique', st: 'stack', sp: 'sell price',
  cs: 'bag slots', ac: 'classes', rs: 'required skill', s: 'stats', ar: 'armor', dm: 'damage', fx: 'effects', set: 'set', c: 'class', sc: 'subclass',
  it: 'slot', d: 'description', ad: 'aura text', r: 'rank', lv: 'level', pw: 'cost', ct: 'cast time', cd: 'cooldown', rg_: 'reagents', rg: 'reagents',
  cr: 'creates', en: 'enchant', tb: 'taught by', lo: 'yellow at', hi: 'grey at', req: 'requires skill', cat: 'category', sl: 'profession'};
function fmtVal(k, v) {
  if (v == null) return '<span class="muted">none</span>';
  if (k === 's') return v.map(x => `${x[1] >= 0 ? '+' : ''}${x[1]} ${STAT_LABEL[x[0]] || M.stats[x[0]] || x[0]}`).join(', ');
  if (k === 'dm') return v.min != null ? `${v.min}-${v.max} (${v.speed}s, ${v.dps} dps)` : `${v.dps} dps`;
  if (k === 'rg_' || k === 'rg') return v.map(x => `${ITEMS[x[0]] ? ITEMS[x[0]].n : '#' + x[0]}${x[1] > 1 ? ' ×' + x[1] : ''}`).join(', ');
  if (k === 'cr') return `${ITEMS[v[0]] ? ITEMS[v[0]].n : '#' + v[0]}${v[1] > 1 ? ' ×' + v[1] : ''}`;
  if (k === 'fx') return v.map(x => `${TRIG[x[0]] || x[0]}: ${SPELLS[x[1]] ? SPELLS[x[1]].n : '#' + x[1]}`).join('; ');
  if (k === 'tb') return v.map(x => ITEMS[x] ? ITEMS[x].n : '#' + x).join(', ');
  if (k === 'sp') return money(v);
  if (k === 'sl') return M.skillLines[v] || v;
  if (k === 'ac') return classList(v);
  if (typeof v === 'object') return esc(JSON.stringify(v));
  return esc(String(v));
}
function patchSection(title, sec, link) {
  const lim = 250;
  const list = (arr, fn) => `<ul>${arr.slice(0, lim).map(fn).join('')}${arr.length > lim ? `<li class="muted">…and ${arr.length - lim} more</li>` : ''}</ul>`;
  let h = `<h3>${title} <span class="muted small">+${sec.added.length} / −${sec.removed.length} / ~${sec.changed.length}</span></h3>`;
  if (!sec.added.length && !sec.removed.length && !sec.changed.length) return h + '<p class="muted">No changes.</p>';
  if (sec.added.length) h += '<h4>Added</h4>' + list(sec.added, a => `<li>${link(a[0], a[1])}</li>`);
  if (sec.removed.length) h += '<h4>Removed</h4>' + list(sec.removed, a => `<li>${esc(a[1])} <span class="muted small">#${a[0]}</span></li>`);
  if (sec.changed.length) h += '<h4>Changed</h4>' + list(sec.changed, a => `<li>${link(a[0], a[1])}<div class="small chg">${Object.entries(a[2]).map(([k, v]) => `${FIELD_NAMES[k] || k}: ${fmtVal(k, v[0])} → ${fmtVal(k, v[1])}`).join('<br>')}</div></li>`);
  return h;
}
function pagePatches(params) {
  if (!PATCHES.length) return `<h1>Patches</h1><p class="muted">Only one build snapshot so far (${M.build}). Diffs appear here once a second Forever build has been snapshotted.</p>`;
  const cur = params.to ? PATCHES.find(p => p.to === params.to) : PATCHES[0];
  const itemLk = (id, n) => ITEMS[id] ? itemLink(id) : esc(n) + ` <span class="muted small">#${id}</span>`;
  const spellLk = (id, n) => SPELLS[id] ? spellLink(id, {rank: true}) : esc(n) + ` <span class="muted small">#${id}</span>`;
  return `<h1>Patches</h1><p class="muted">Client data diffs between consecutive Forever builds snapshotted by the build script. Builds: ${M.builds.join(' → ')}.</p>
  <div class="tabs">${PATCHES.map(p => `<a href="#/patches?to=${p.to}" class="${p === cur ? 'on' : ''}">${p.from} → ${p.to}</a>`).join('')}</div>
  <h2>${cur.from} → ${cur.to} <span class="muted small">snapshotted ${cur.date}</span></h2>
  <div class="row"><div class="col">${patchSection('Recipes', cur.recipes, spellLk)}${patchSection('Items', cur.items, itemLk)}</div><div class="col">${patchSection('Spells', cur.spells, spellLk)}</div></div>`;
}

function pageSearch(params) {
  const q = params.q || '';
  const r = search(q, 300);
  return `<h1>Search: ${esc(q)}</h1>${r.length ? `<ul>${r.map(e => `<li>${resultLink(e)} <span class="muted small">${e.t}</span></li>`).join('')}</ul>` : '<p class="muted">No matches.</p>'}`;
}

/* ---------------------------------------------------------------- router */
function parseHash() {
  const h = location.hash.replace(/^#\/?/, '');
  const [path, qs] = h.split('?');
  const params = {};
  (qs || '').split('&').forEach(kv => { if (!kv) return; const [k, v] = kv.split('='); params[decodeURIComponent(k)] = decodeURIComponent(v || ''); });
  return {parts: path.split('/').filter(Boolean), params};
}
let lastPath = '';
function render() {
  const {parts, params} = parseHash();
  const [p, id] = parts;
  const path = parts.join('/');
  if (p === 'items' && params.flag && path !== lastPath) { STATE.items = {q: '', c: '', sc: '', qmin: '', lmin: '', lmax: '', flag: params.flag}; }
  if (p === 'profession' && path !== lastPath) { STATE.prof = {q: '', skill: STATE.prof.skill, flag: params.new ? 'new' : '', hideGrey: false}; }
  let html;
  switch (p) {
    case undefined: html = pageHome(); break;
    case 'professions': html = pageProfessions(); break;
    case 'profession': html = pageProfession(id, params); break;
    case 'item': html = pageItem(id); break;
    case 'items': html = pageItems(); break;
    case 'spell': html = pageSpell(id); break;
    case 'classes': html = pageClasses(); break;
    case 'class': html = pageClass(id); break;
    case 'line': html = pageLine(id); break;
    case 'sets': html = pageSets(); break;
    case 'set': html = pageSet(id); break;
    case 'zones': html = pageZones(); break;
    case 'zone': html = pageZone(id); break;
    case 'new': html = pageNew(); break;
    case 'search': html = pageSearch(params); break;
    case 'patches': html = pagePatches(params); break;
    case 'maps': html = pageMaps(); break;
    case 'map': html = pageMap(id); break;
    default: html = '<h1>Not found</h1>';
  }
  $('#main').innerHTML = html;
  if (p === 'profession') bindProfession();
  if (p === 'items') bindItems();
  if (p === 'class') bindClass();
  if (path !== lastPath) { window.scrollTo(0, 0); lastPath = path; }
  $('#tip').hidden = true;
  const h1 = $('#main h1');
  const t = h1 ? [...h1.childNodes].filter(n => !(n.classList && n.classList.contains('badge'))).map(n => n.textContent).join('').trim() : '';
  document.title = (t ? t + ' – ' : '') + 'Forever Ref';
}
window.addEventListener('hashchange', render);
render();
